/**
 * Each token as `var(--name)`, so a value still follows the theme and the breakpoint.
 *
 * Indexing with a name that does not exist is a compile error, which is the whole point:
 * a mistyped custom property in a plain string resolves to nothing and renders as though
 * it were a decision.
 */
export declare const tokens: Readonly<Record<TokenName, string>>;
